(function() {
  'use strict';

  const section = document.getElementById('revised-tfp-gdp');
  if (!section) return;

  // Data source mapping from evidence
  const sources = {
    'S009': { id: 'pdf-b0183405d850db11-p2-b4', page: 2 },
    'S996': { id: 'pdf-b0183405d850db11-p36-b3', page: 36 },
    'S139': { id: 'pdf-b0183405d850db11-p7-b8', page: 7 },
    'S997': { id: 'pdf-b0183405d850db11-p36-b4', page: 36 }
  };

  // Attach event listeners to source buttons
  const buttons = section.querySelectorAll('.source-btn');
  buttons.forEach(btn => {
    btn.addEventListener('click', (e) => {
      const sourceId = e.currentTarget.getAttribute('data-source');
      if (sources[sourceId]) {
        // Dispatch custom event for host kernel to handle
        const event = new CustomEvent('papermind:source-request', {
          bubbles: true,
          detail: {
            sourceId: sources[sourceId].id,
            page: sources[sourceId].page,
            triggerElement: e.currentTarget
          }
        });
        document.dispatchEvent(event);
      }
    });
  });

  // Initialize animation for bars on load
  const bars = section.querySelectorAll('.bar-fill');
  bars.forEach(bar => {
    const width = bar.style.width;
    bar.style.width = '0';
    setTimeout(() => {
      bar.style.width = width;
    }, 100);
  });

})();
